const r = await Promise.allSettled([
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g 'ProfileSettings.tsx' -g '*Share*Dialog*' -g 'ExternalLink.tsx' -g '*ExternalLink.scss' src .",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"rg -n '(<a\\b|target=|external-link|external_link|externalLink|ExternalLink|share.*link|Link to room)' src/components/views/settings src/components/views/dialogs src/components/views/elements 2>/dev/null",workdir:"/app",max_output_tokens:12000})
]); for (const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name ProfileSettings.tsx -o -name '*Share*Dialog*' -o -name ExternalLink.tsx -o -name '*ExternalLink.scss'",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"grep -RInE '(<a([[:space:]>])|target=|external-link|external_link|externalLink|ExternalLink|Link to room)' src/components/views/settings src/components/views/dialogs src/components/views/elements",workdir:"/app",max_output_tokens:15000})
]); for (const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

